# *args — позиционные аргументы как tuple
def add(*args):
    return sum(args)
add(1, 2, 3)  # 6

# **kwargs — именованные аргументы как dict
def info(**kwargs):
    for k, v in kwargs.items():
        print(f'{k}: {v}')
info(name='Alice', age=30)

