# Генераторная функция
def squares(n):
    for i in range(n):
        yield i ** 2

for x in squares(5):
    print(x)  # 0 1 4 9 16

# Генераторное выражение (как list, но ленивое)
gen = (x**2 for x in range(100))  # не создаёт список
next(gen)  # 0
